import React from 'react';

import { svgPlotLayout } from '../../../core/components/chart-grid/ChartGridRoot.sty.js';
import { useGridPlotSize } from '../../../core/components/chart-grid/hooks/useGridPlotSize.js';
import { useHistogramXScale } from '../../hooks/useHistogramXScale.js';
import { useHistogramYScales } from '../../hooks/useHistogramYScales.js';
import { Grid } from '../grid/Grid.js';

export const HistogramChartGridLayout = () => {
  const { width, height } = useGridPlotSize();
  const [leftScale] = useHistogramYScales();
  const { xScale } = useHistogramXScale();

  return (
    <svg className={svgPlotLayout}>
      <Grid xScale={xScale} yScale={leftScale} height={height} width={width} />
    </svg>
  );
};

HistogramChartGridLayout['displayName'] = 'HistogramChartGridLayout';
